<template><div class="page"><h2 class="page-title">看懂你的消费习惯</h2><p class="muted">净消费＝实际消费－退款；转账、充值和提现不算日常消费。</p><el-alert v-if="data.has_data" title="先看周度趋势判断近期是否偏高，再看类别占比决定预算从哪里调整。单个异常周不代表习惯已经改变。" type="info" :closable="false"/><div v-if="data.has_data" class="grid section"><div class="card wide"><h3>每周净消费</h3><p class="muted">用于观察短期波动，也是后续预算的主要时间单位。</p><EChart :option="weekly"/></div><div class="card wide"><h3>每月消费与退款</h3><EChart :option="monthly"/></div><div class="card wide"><h3>消费类别占比</h3><EChart :option="category"/></div><div class="card wide"><h3>工作日与周末日均</h3><EChart :option="dayType"/></div><div class="card full"><h3>主要分类周度趋势</h3><EChart :option="categoryTrend"/></div><div class="card full"><h3>需要留意的异常周</h3><p class="muted">按完整周统计规则识别；异常只表示与平时差异较大，不等于不合理消费。</p><el-table :data="data.anomaly_weeks"><el-table-column prop="week_start" label="周开始"/><el-table-column label="净消费"><template #default="s">{{formatMoney(s.row.net_consumption_minor)}}</template></el-table-column><el-table-column prop="large_transaction_count" label="较大金额交易数"/><el-table-column label="变化方向"><template #default="s">{{s.row.anomaly_direction==='high'?'高于平时':'低于平时'}}</template></el-table-column></el-table></div></div><div v-if="data.has_data" class="next-step"><div><b>下一步：设置储蓄目标</b><p class="muted">收入由你填写，系统不会把微信转入误当工资。</p></div><el-button type="primary" @click="$router.push('/goals')">设置储蓄目标</el-button></div><EmptyGuide v-else description="暂无可分析交易" hint="请先导入账单，系统才有真实消费数据。" action="/bills" action-text="导入账单"/></div></template>
<script setup>
import { computed,onMounted,ref } from 'vue';import { ElMessage } from 'element-plus';import { api } from '../api/client.js';import EChart from '../components/EChart.vue';import EmptyGuide from '../components/EmptyGuide.vue';import { formatMoney } from '../utils/money.js';import { categoryName } from '../utils/display.js'
const data=ref({});onMounted(async()=>{try{data.value=await api.get('/analytics/overview')}catch(e){ElMessage.error(e.message)}});const tip={trigger:'axis',valueFormatter:v=>formatMoney(v)}
const weekly=computed(()=>({tooltip:tip,xAxis:{type:'category',data:(data.value.weekly||[]).map(x=>x.week_start)},yAxis:{type:'value'},series:[{type:'line',smooth:true,data:(data.value.weekly||[]).map(x=>x.net_consumption_minor),color:'#2b9a72'}]}));const monthly=computed(()=>({tooltip:tip,legend:{},xAxis:{type:'category',data:(data.value.monthly||[]).map(x=>x.year_month)},yAxis:{type:'value'},series:['gross_consumption_minor','refund_minor','net_consumption_minor'].map((k,i)=>({name:['实际消费','退款','净消费'][i],type:'bar',data:(data.value.monthly||[]).map(x=>x[k])}))}));const category=computed(()=>({tooltip:{trigger:'item',valueFormatter:v=>formatMoney(v)},series:[{type:'pie',radius:['45%','70%'],data:(data.value.categories||[]).map(x=>({name:categoryName(x.category_code),value:x.net_consumption_minor}))}]}));const dayType=computed(()=>({tooltip:tip,xAxis:{type:'category',data:(data.value.weekday_weekend||[]).map(x=>x.is_weekend?'周末':'工作日')},yAxis:{type:'value'},series:[{type:'bar',data:(data.value.weekday_weekend||[]).map(x=>x.daily_average_minor),color:'#4d7c72'}]}));const categoryTrend=computed(()=>{const top=(data.value.categories||[]).slice().sort((a,b)=>b.net_consumption_minor-a.net_consumption_minor).slice(0,5).map(x=>x.category_code),weeks=[...new Set((data.value.category_weekly||[]).map(x=>x.week_start))];return{tooltip:tip,legend:{},xAxis:{type:'category',data:weeks},yAxis:{type:'value'},series:top.map(code=>({name:categoryName(code),type:'line',showSymbol:false,data:weeks.map(w=>(data.value.category_weekly||[]).find(x=>x.week_start===w&&x.category_code===code)?.net_consumption_minor||0)}))}})
</script>
